//! Native gh/glab workflows. Typed plans are reviewed before every remote write; CLI
//! credentials stay in the CLI's store and commands never run from the project folder.
use rc_core::{Inbox,Waker};
use rc_kit::i18n::tr;
use serde_json::{Value,json};
use std::{path::{Path,PathBuf},process::Stdio,time::Duration};
use tokio::io::{AsyncReadExt,AsyncWriteExt};
pub use rc_core::session::IssueTrackerConfig as Config;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum Kind{Version,Account,Requests,Request(u64),Diff,Runs,Jobs,Logs,Write}
#[derive(Clone,Debug)]
pub enum Operation{Version,Account,Requests,Request(u64),Diff(u64),Runs,Jobs(u64),Logs{run:u64,job:u64},Create{title:String,body:String,base:String,head:String,draft:bool},Review{number:u64,sha:String,event:String,body:String},Fork,Snippet{title:String,name:String,content:String,public:bool},Pipeline{number:u64,retry:bool}}
#[derive(Clone,Debug)]
pub struct Plan{program:PathBuf,pub args:Vec<String>,pub body:Option<Vec<u8>>,pub write:bool,pub endpoint:String,pub kind:Kind,config:Config,pub account:Option<String>}
#[derive(Debug)]
pub enum Error{Trust,Input,Missing,Account,Changed,Unconfirmed,Cancelled,Limit,Payload,Io,Failed(String)}
impl Error{fn message(&self)->String{match self{Self::Trust=>tr("Trust this project before running project tools or code").into(),Self::Input=>tr("Choose a valid hosting service, HTTPS origin, project and operation fields").into(),Self::Missing=>tr("Install gh or glab, or choose its executable, then check the CLI").into(),Self::Account=>tr("Load the active CLI account before previewing a remote write").into(),Self::Changed=>tr("The active CLI account changed; review the operation again").into(),Self::Unconfirmed=>tr("Review and confirm this exact remote operation before sending").into(),Self::Cancelled=>tr("Hosting operation cancelled locally; a remote write may already have completed. Check the service before retrying.").into(),Self::Limit=>tr("Hosting input, output or execution time exceeded its safety limit").into(),Self::Payload=>tr("The hosting service returned an unsupported response").into(),Self::Io=>tr("Could not start or communicate with the hosting CLI").into(),Self::Failed(text)=>text.clone()}}}
fn github(config:&Config)->bool{config.provider=="github"}
fn host(config:&Config)->Result<String,Error>{if !matches!(config.provider.as_str(),"github"|"gitlab")||config.base_url.len()>2048{return Err(Error::Input);}let url=reqwest::Url::parse(&config.base_url).map_err(|_|Error::Input)?;if url.scheme()!="https"||url.host_str().is_none()||!url.username().is_empty()||url.password().is_some()||url.path()!="/"||url.query().is_some()||url.fragment().is_some(){return Err(Error::Input);}let name=url.host_str().ok_or(Error::Input)?;if name.starts_with('-'){return Err(Error::Input);}Ok(match url.port(){Some(port)=>format!("{name}:{port}"),None=>name.into()})}
fn repository(config:&Config)->Result<String,Error>{let parts:Vec<_>=config.project.split('/').collect();if parts.len()<2||(github(config)&&parts.len()!=2)||config.project.len()>512||parts.iter().any(|part|part.is_empty()||matches!(*part,"."|"..")||!part.chars().all(|c|c.is_ascii_alphanumeric()||matches!(c,'_'|'-'|'.'))){return Err(Error::Input);}Ok(if github(config){format!("repos/{}",config.project)}else{format!("projects/{}",config.project.replace('/',"%2F"))})}
fn nonempty(value:&str,max:usize)->Result<(),Error>{if value.trim().is_empty()||value.len()>max||value.contains('\0'){Err(Error::Input)}else{Ok(())}}
fn hash(value:&str)->bool{matches!(value.len(),40|64)&&value.bytes().all(|b|b.is_ascii_hexdigit())}
fn id(value:u64)->Result<u64,Error>{if value==0{Err(Error::Input)}else{Ok(value)}}
pub fn plan(config:&Config,program:&Path,operation:Operation,account:Option<String>)->Result<Plan,Error>{
    let hostname=host(config)?;if program.as_os_str().is_empty(){return Err(Error::Missing);}let gh=github(config);let mut endpoint=String::new();let mut body=None;let mut kind=Kind::Write;let mut method="GET";let mut extra=Vec::new();
    match operation{
        Operation::Version=>{return Ok(Plan{program:program.into(),args:vec!["--version".into()],body:None,write:false,endpoint:String::new(),kind:Kind::Version,config:config.clone(),account:None});},
        Operation::Account=>{endpoint="user".into();kind=Kind::Account;},
        Operation::Requests=>{endpoint=format!("{}/{}?state={}&per_page=50",repository(config)?,if gh{"pulls"}else{"merge_requests"},if gh{"open"}else{"opened"});kind=Kind::Requests;},
        Operation::Request(number)=>{endpoint=format!("{}/{}/{}",repository(config)?,if gh{"pulls"}else{"merge_requests"},id(number)?);kind=Kind::Request(number);},
        Operation::Diff(number)=>{endpoint=format!("{}/{}/{}{}",repository(config)?,if gh{"pulls"}else{"merge_requests"},id(number)?,if gh{""}else{"/raw_diffs"});if gh{extra=vec!["--header".into(),"Accept: application/vnd.github.diff".into()];}kind=Kind::Diff;},
        Operation::Runs=>{endpoint=format!("{}/{}?per_page=50",repository(config)?,if gh{"actions/runs"}else{"pipelines"});kind=Kind::Runs;},
        Operation::Jobs(number)=>{endpoint=format!("{}/{}/{}/jobs?per_page=50",repository(config)?,if gh{"actions/runs"}else{"pipelines"},id(number)?);kind=Kind::Jobs;},
        Operation::Logs{run,job}=>{id(run)?;id(job)?;repository(config)?;if gh{return Ok(Plan{program:program.into(),args:vec!["run".into(),"view".into(),run.to_string(),"--job".into(),job.to_string(),"--log".into(),"--repo".into(),format!("{hostname}/{}",config.project)],body:None,write:false,endpoint:format!("actions/jobs/{job}/logs"),kind:Kind::Logs,config:config.clone(),account:None});}endpoint=format!("{}/jobs/{job}/trace",repository(config)?);kind=Kind::Logs;},
        Operation::Create{title,body:description,base,head,draft}=>{nonempty(&title,512)?;nonempty(&base,255)?;nonempty(&head,255)?;if description.len()>16*1024{return Err(Error::Limit);}endpoint=format!("{}/{}",repository(config)?,if gh{"pulls"}else{"merge_requests"});body=Some(if gh{json!({"title":title,"body":description,"base":base,"head":head,"draft":draft})}else{json!({"title":if draft{format!("Draft: {title}")}else{title},"description":description,"target_branch":base,"source_branch":head})});},
        Operation::Review{number,sha,event,body:text}=>{id(number)?;if !hash(&sha)||text.len()>16*1024{return Err(Error::Input);}if !matches!(event.as_str(),"COMMENT"|"APPROVE"|"REQUEST_CHANGES")||(!gh&&event=="REQUEST_CHANGES"){return Err(Error::Input);}if event!="APPROVE"{nonempty(&text,16*1024)?;}endpoint=format!("{}/{}/{}/{}",repository(config)?,if gh{"pulls"}else{"merge_requests"},number,if gh{"reviews"}else if event=="APPROVE"{"approve"}else{"notes"});body=Some(if gh{json!({"event":event,"body":text,"commit_id":sha})}else if event=="APPROVE"{json!({"sha":sha})}else{json!({"body":text})});},
        Operation::Fork=>{endpoint=format!("{}/{}",repository(config)?,if gh{"forks"}else{"fork"});body=Some(json!({}));},
        Operation::Snippet{title,name,content,public}=>{nonempty(&title,512)?;nonempty(&content,64*1024)?;if name.is_empty()||name.len()>120||matches!(name.as_str(),"."|"..")||!name.chars().all(|c|c.is_ascii_alphanumeric()||matches!(c,'_'|'-'|'.')){return Err(Error::Input);}endpoint=if gh{"gists"}else{"snippets"}.into();body=Some(if gh{json!({"description":title,"public":public,"files":{name:{"content":content}}})}else{json!({"title":title,"visibility":if public{"public"}else{"private"},"files":[{"file_path":name,"content":content}]})});},
        Operation::Pipeline{number,retry}=>{endpoint=format!("{}/{}/{}/{}",repository(config)?,if gh{"actions/runs"}else{"pipelines"},id(number)?,if retry{if gh{"rerun"}else{"retry"}}else{"cancel"});body=Some(json!({}));},
    }
    let write=kind==Kind::Write;if write{method="POST";if account.as_ref().is_none_or(|s|s.is_empty()||s.len()>128){return Err(Error::Account);}}
    let body=body.map(|body|serde_json::to_vec(&body).map_err(|_|Error::Input)).transpose()?;if body.as_ref().is_some_and(|b|b.len()>128*1024){return Err(Error::Limit);}
    let mut args=vec!["api".into(),"--hostname".into(),hostname,"--method".into(),method.into(),endpoint.clone()];args.extend(extra);if body.is_some(){args.extend(["--input".into(),"-".into()]);}
    Ok(Plan{program:program.into(),args,body,write,endpoint,kind,config:config.clone(),account})
}
struct Group(Option<u32>);impl Drop for Group{fn drop(&mut self){if let Some(pid)=self.0{rc_dotnet::kill_tree(pid);}}}
async fn command(plan:&Plan,cancel:&rc_dotnet::CancelToken)->Result<Vec<u8>,Error>{
    if cancel.is_cancelled(){return Err(Error::Cancelled);}let neutral=tempfile::tempdir().map_err(|_|Error::Io)?;let mut cmd=tokio::process::Command::new(&plan.program);cmd.args(&plan.args).current_dir(neutral.path()).stdin(if plan.body.is_some(){Stdio::piped()}else{Stdio::null()}).stdout(Stdio::piped()).stderr(Stdio::piped()).kill_on_drop(true);
    for key in ["GH_DEBUG","GLAB_DEBUG","GLAB_DEBUG_HTTP","GH_REPO","GH_HOST","GITLAB_HOST","GITLAB_URI","GITLAB_URL","GLAB_HOST","GIT_DIR","GIT_WORK_TREE","GIT_INDEX_FILE"]{cmd.env_remove(key);}
    for(key,value)in[("GH_PROMPT_DISABLED","1"),("GH_NO_UPDATE_NOTIFIER","1"),("GLAB_CHECK_UPDATE","false"),("GIT_TERMINAL_PROMPT","0"),("NO_COLOR","1"),("CLICOLOR","0"),("GH_PAGER","cat"),("GLAB_PAGER","cat"),("PAGER","cat"),("EDITOR",":"),("VISUAL",":")]{cmd.env(key,value);}
    #[cfg(unix)]cmd.process_group(0);#[cfg(windows)]cmd.creation_flags(0x0800_0000);
    let mut child=cmd.spawn().map_err(|e|if e.kind()==std::io::ErrorKind::NotFound{Error::Missing}else{Error::Io})?;let mut group=Group(child.id());let stdout=child.stdout.take().ok_or(Error::Io)?;let stderr=child.stderr.take().ok_or(Error::Io)?;let stdin=child.stdin.take();let body=plan.body.clone();
    let work=async{let out=async{let mut out=Vec::new();stdout.take(2*1024*1024+1).read_to_end(&mut out).await.map_err(|_|Error::Io)?;if out.len()>2*1024*1024{return Err(Error::Limit);}Ok::<_,Error>(out)};let err=async{let mut err=Vec::new();stderr.take(64*1024+1).read_to_end(&mut err).await.map_err(|_|Error::Io)?;if err.len()>64*1024{return Err(Error::Limit);}Ok::<_,Error>(err)};let input=async{if let(Some(mut pipe),Some(body))=(stdin,body){let _=pipe.write_all(&body).await;let _=pipe.shutdown().await;}Ok::<_,Error>(())};let(out,err,())=tokio::try_join!(out,err,input)?;let status=child.wait().await.map_err(|_|Error::Io)?;Ok::<_,Error>((out,err,status.success()))};
    let result=tokio::select!{result=tokio::time::timeout(Duration::from_secs(60),work)=>result.map_err(|_|Error::Limit)?,()=cancel.cancelled()=>return Err(Error::Cancelled)}?;group.0=None;
    if !result.2{return Err(Error::Failed(rc_dotnet::strip_ansi(&String::from_utf8_lossy(&result.1)).chars().take(8192).collect()));}Ok(result.0)
}
fn username(config:&Config,bytes:&[u8])->Result<String,Error>{let value:Value=serde_json::from_slice(bytes).map_err(|_|Error::Payload)?;let name=value.get(if github(config){"login"}else{"username"}).and_then(|v|v.as_str()).ok_or(Error::Payload)?;nonempty(name,128)?;Ok(name.into())}
pub async fn execute(plan:&Plan,trusted:bool,confirmed:bool,cancel:&rc_dotnet::CancelToken)->Result<Vec<u8>,Error>{
    if !trusted{return Err(Error::Trust);}if plan.write&&!confirmed{return Err(Error::Unconfirmed);}if plan.write{let account=self::plan(&plan.config,&plan.program,Operation::Account,None)?;let current=username(&plan.config,&command(&account,cancel).await?)?;if Some(&current)!=plan.account.as_ref(){return Err(Error::Changed);}}
    command(plan,cancel).await
}

#[derive(Clone,Debug)]
pub struct Item{pub id:u64,pub title:String,pub state:String}
fn items(kind:Kind,gh:bool,value:&Value)->Result<Vec<Item>,Error>{let array=match kind{Kind::Requests=>value.as_array(),Kind::Runs=>if gh{value.get("workflow_runs").and_then(Value::as_array)}else{value.as_array()},Kind::Jobs=>if gh{value.get("jobs").and_then(Value::as_array)}else{value.as_array()},_=>return Ok(Vec::new())}.ok_or(Error::Payload)?;if array.len()>100{return Err(Error::Limit);}array.iter().map(|row|{let id=row.get(match kind{Kind::Requests=>if gh{"number"}else{"iid"},_=>"id"}).and_then(Value::as_u64).filter(|n|*n>0).ok_or(Error::Payload)?;let title=["title","name","ref"].into_iter().find_map(|key|row.get(key).and_then(Value::as_str)).unwrap_or("").chars().take(300).collect();let state=row.get("state").or_else(||row.get("status")).and_then(Value::as_str).unwrap_or("").chars().take(40).collect();Ok(Item{id,title,state})}).collect()}
struct Event{kind:Kind,result:Result<Vec<u8>,Error>}
pub enum UiAction{Login{program:String,args:Vec<String>},UseFile}
pub struct Hosting{
    pub config:Config,pub executable:String,pub verified:bool,pub account:Option<String>,pub rows:Vec<Item>,pub request_id:u64,pub run_id:u64,pub job_id:u64,
    pub title:String,pub body:String,pub base:String,pub head:String,pub draft:bool,pub snippet_name:String,pub snippet_content:String,pub public:bool,
    pending:Option<Plan>,confirmed:bool,sha:String,sha_for:Option<u64>,list_kind:Kind,output:String,error:Option<String>,inbox:Inbox<Event>,cancel:Option<rc_dotnet::CancelToken>,
}
impl Hosting{
    pub fn new(waker:Waker)->Self{Self{config:Config{provider:"github".into(),base_url:"https://github.com".into(),project:String::new()},executable:"gh".into(),verified:false,account:None,rows:Vec::new(),request_id:1,run_id:1,job_id:1,title:String::new(),body:String::new(),base:"main".into(),head:String::new(),draft:true,snippet_name:"main.rs".into(),snippet_content:String::new(),public:false,pending:None,confirmed:false,sha:String::new(),sha_for:None,list_kind:Kind::Requests,output:String::new(),error:None,inbox:Inbox::new(waker),cancel:None}}
    pub fn restore(&mut self,config:Option<Config>){if let Some(config)=config{if host(&config).is_ok()&&config.project.len()<=512{self.executable=if github(&config){"gh"}else{"glab"}.into();self.config=config;}}}
    pub fn cancel(&self){if let Some(cancel)=&self.cancel{cancel.cancel();}}
    fn invalidate(&mut self){self.pending=None;self.confirmed=false;}
    fn start(&mut self,plan:Plan,trusted:bool,confirmed:bool){if self.cancel.is_some(){return;}let cancel=rc_dotnet::CancelToken::new();self.cancel=Some(cancel.clone());self.error=None;let out=self.inbox.sender();rc_core::Runtime::spawn(async move{let result=execute(&plan,trusted,confirmed,&cancel).await;out.send(Event{kind:plan.kind,result});});}
    fn read(&mut self,operation:Operation,trusted:bool){if !self.verified&&!matches!(operation,Operation::Version){self.error=Some(Error::Missing.message());return;}match plan(&self.config,Path::new(&self.executable),operation,None){Ok(plan)=>self.start(plan,trusted,false),Err(error)=>self.error=Some(error.message())}}
    fn prepare(&mut self,operation:Operation){self.invalidate();if !self.verified{self.error=Some(Error::Missing.message());return;}match plan(&self.config,Path::new(&self.executable),operation,self.account.clone()){Ok(plan)=>{self.pending=Some(plan);self.error=None;},Err(error)=>self.error=Some(error.message())}}
    pub fn use_file(&mut self,name:String,content:String){self.invalidate();if content.len()>64*1024{self.error=Some(Error::Limit.message());return;}self.snippet_name=name;self.snippet_content=content;}
    pub fn poll(&mut self){for event in self.inbox.drain(){self.cancel=None;match event.result{Err(error)=>self.error=Some(error.message()),Ok(bytes)=>{self.output=rc_dotnet::strip_ansi(&String::from_utf8_lossy(&bytes)).chars().take(64*1024).collect();if event.kind==Kind::Version{let prefix=if github(&self.config){"gh version"}else{"glab version"};self.verified=self.output.trim_start().starts_with(prefix);if !self.verified{self.error=Some(Error::Missing.message());}continue;}if matches!(event.kind,Kind::Diff|Kind::Logs){continue;}if bytes.is_empty()&&event.kind==Kind::Write{continue;}let value:Value=match serde_json::from_slice(&bytes){Ok(value)=>value,Err(_)=>{self.error=Some(Error::Payload.message());continue;}};match event.kind{Kind::Account=>match username(&self.config,&bytes){Ok(account)=>{self.account=Some(account);self.invalidate();},Err(error)=>self.error=Some(error.message())},Kind::Requests|Kind::Runs|Kind::Jobs=>match items(event.kind,github(&self.config),&value){Ok(rows)=>{self.rows=rows;self.list_kind=event.kind;},Err(error)=>self.error=Some(error.message())},Kind::Request(number)=>{self.sha=value.get("head").and_then(|v|v.get("sha")).or_else(||value.get("sha")).and_then(Value::as_str).filter(|sha|hash(sha)).unwrap_or("").into();self.sha_for=Some(number);},_=>{}}}}}}
    pub fn show(&mut self,ui:&mut egui::Ui,trusted:bool)->(Option<UiAction>,bool){
        let mut action=None;let mut config_changed=false;let busy=self.cancel.is_some();let gh=github(&self.config);
        egui::ScrollArea::vertical().id_salt("hosting_body").show(ui,|ui|{
            ui.label(tr("Uses gh/glab credentials. Nothing runs on project open. CLI processes run outside the project without its environment."));
            ui.add_enabled_ui(!busy,|ui|{
                ui.horizontal(|ui|{ui.label(tr("Hosting service"));egui::ComboBox::from_id_salt("hosting_service").selected_text(if gh{"GitHub"}else{"GitLab"}).show_ui(ui,|ui|{for(provider,title,url,exe)in[("github","GitHub","https://github.com","gh"),("gitlab","GitLab","https://gitlab.com","glab")]{if ui.selectable_value(&mut self.config.provider,provider.into(),title).changed(){self.config.base_url=url.into();self.executable=exe.into();config_changed=true;}}});});
                ui.horizontal(|ui|{ui.label(tr("Service HTTPS origin"));config_changed|=ui.add(egui::TextEdit::singleline(&mut self.config.base_url).char_limit(2048).desired_width(300.0)).changed();ui.label(tr("Namespace/project"));config_changed|=ui.add(egui::TextEdit::singleline(&mut self.config.project).char_limit(512)).changed();});
                ui.horizontal(|ui|{ui.label(tr("CLI executable"));if ui.add(egui::TextEdit::singleline(&mut self.executable).char_limit(4096)).changed(){config_changed=true;}if config_changed{self.verified=false;self.account=None;self.rows.clear();self.sha_for=None;self.invalidate();}if ui.button(tr("Check CLI")).clicked(){self.read(Operation::Version,trusted);}if ui.add_enabled(self.verified,egui::Button::new(tr("Load CLI Account"))).clicked(){self.read(Operation::Account,trusted);}if ui.add_enabled(self.verified,egui::Button::new(tr("Log In in Terminal"))).clicked(){match host(&self.config){Ok(host)=>{let mut args=vec!["auth".into(),"login".into(),"--hostname".into(),host];if github(&self.config){args.push("--web".into());}self.account=None;self.invalidate();action=Some(UiAction::Login{program:self.executable.clone(),args});},Err(error)=>self.error=Some(error.message())}}});
            });
            if let Some(account)=&self.account{ui.label(format!("{}: {account}",tr("Active CLI account")));}
            if let Some(error)=&self.error{ui.colored_label(rc_kit::pal(ui).error,error);}
            if busy{ui.horizontal(|ui|{ui.spinner();if ui.button(tr("Cancel")).clicked(){self.cancel();}});}
            ui.add_enabled_ui(self.verified&&!busy,|ui|{
                ui.horizontal(|ui|{if ui.button(tr("List Pull/Merge Requests")).clicked(){self.read(Operation::Requests,trusted);}ui.label(tr("Request number"));if ui.add(egui::DragValue::new(&mut self.request_id).range(1..=u64::MAX)).changed(){self.sha_for=None;self.invalidate();}if ui.button(tr("Load Request Details")).clicked(){self.read(Operation::Request(self.request_id),trusted);}if ui.button(tr("Load Request Diff")).clicked(){self.read(Operation::Diff(self.request_id),trusted);}});
                ui.horizontal(|ui|{if ui.button(tr("List Actions/CI Runs")).clicked(){self.read(Operation::Runs,trusted);}ui.label(tr("Run/Pipeline ID"));if ui.add(egui::DragValue::new(&mut self.run_id).range(1..=u64::MAX)).changed(){self.invalidate();}if ui.button(tr("List Jobs")).clicked(){self.read(Operation::Jobs(self.run_id),trusted);}ui.label(tr("Job ID"));ui.add(egui::DragValue::new(&mut self.job_id).range(1..=u64::MAX));if ui.button(tr("Load Job Logs")).clicked(){self.read(Operation::Logs{run:self.run_id,job:self.job_id},trusted);}});
            });
            egui::ScrollArea::vertical().id_salt("hosting_rows").max_height(140.0).show(ui,|ui|{for item in &self.rows{if ui.selectable_label(false,format!("{} · {} · {}",item.id,item.title,item.state)).clicked(){match self.list_kind{Kind::Requests=>{self.request_id=item.id;self.sha_for=None;},Kind::Runs=>self.run_id=item.id,Kind::Jobs=>self.job_id=item.id,_=>{}}self.pending=None;self.confirmed=false;}}});
            ui.add_enabled_ui(self.verified&&!busy,|ui|{
                egui::CollapsingHeader::new(tr("Create Pull/Merge Request")).show(ui,|ui|{let mut changed=false;ui.label(tr("Title"));changed|=ui.add(egui::TextEdit::singleline(&mut self.title).char_limit(512)).changed();ui.label(tr("Message / Description"));changed|=ui.add(egui::TextEdit::multiline(&mut self.body).char_limit(16*1024).desired_rows(3)).changed();ui.horizontal(|ui|{ui.label(tr("Target branch"));changed|=ui.add(egui::TextEdit::singleline(&mut self.base).char_limit(255)).changed();ui.label(tr("Source branch"));changed|=ui.add(egui::TextEdit::singleline(&mut self.head).char_limit(255)).changed();changed|=ui.checkbox(&mut self.draft,tr("Draft request")).changed();});if changed{self.invalidate();}if ui.button(tr("Preview Request Creation")).clicked(){self.prepare(Operation::Create{title:self.title.clone(),body:self.body.clone(),base:self.base.clone(),head:self.head.clone(),draft:self.draft});}});
                egui::CollapsingHeader::new(tr("Review Pull/Merge Request")).show(ui,|ui|{ui.label(tr("Load request details first. Reviews target the fetched head commit; GitLab supports comments and approval."));ui.label(&self.sha);if ui.add(egui::TextEdit::multiline(&mut self.body).char_limit(16*1024).desired_rows(3)).changed(){self.invalidate();}ui.add_enabled_ui(self.sha_for==Some(self.request_id)&&hash(&self.sha),|ui|{ui.horizontal(|ui|{for(event,label)in[("COMMENT",tr("Preview Review Comment")),("APPROVE",tr("Preview Approval")),("REQUEST_CHANGES",tr("Preview Changes Requested"))]{if ui.add_enabled(gh||event!="REQUEST_CHANGES",egui::Button::new(label)).clicked(){self.prepare(Operation::Review{number:self.request_id,sha:self.sha.clone(),event:event.into(),body:self.body.clone()});}}});});});
                egui::CollapsingHeader::new(tr("Fork / CI Operations")).show(ui,|ui|{ui.label(tr("Fork creates a remote fork in the active account without cloning or adding a local remote."));ui.horizontal(|ui|{if ui.button(tr("Preview Fork")).clicked(){self.prepare(Operation::Fork);}if ui.button(tr("Preview CI Retry")).clicked(){self.prepare(Operation::Pipeline{number:self.run_id,retry:true});}if ui.button(tr("Preview CI Cancellation")).clicked(){self.prepare(Operation::Pipeline{number:self.run_id,retry:false});}});});
                egui::CollapsingHeader::new(tr("Publish Gist / Snippet")).show(ui,|ui|{if gh{ui.colored_label(rc_kit::pal(ui).warn,tr("Secret GitHub gists are unlisted, not access-controlled. Review all content before publishing."));}let mut changed=false;ui.label(tr("Title"));changed|=ui.add(egui::TextEdit::singleline(&mut self.title).char_limit(512)).changed();ui.horizontal(|ui|{ui.label(tr("File name"));changed|=ui.add(egui::TextEdit::singleline(&mut self.snippet_name).char_limit(120)).changed();changed|=ui.checkbox(&mut self.public,tr("Public sharing")).changed();if ui.button(tr("Use Active File Content")).clicked(){action=Some(UiAction::UseFile);}});changed|=ui.add(egui::TextEdit::multiline(&mut self.snippet_content).font(egui::TextStyle::Monospace).char_limit(64*1024).desired_rows(4)).changed();if changed{self.invalidate();}if ui.button(tr("Preview Gist / Snippet")).clicked(){self.prepare(Operation::Snippet{title:self.title.clone(),name:self.snippet_name.clone(),content:self.snippet_content.clone(),public:self.public});}});
            });
            if let Some(plan)=self.pending.clone(){ui.separator();ui.colored_label(rc_kit::pal(ui).warn,tr("Remote write preview: verify the account, host, project and content. CI operations may start or stop remote work."));ui.label(format!("POST · {} · {} · {}",plan.account.as_deref().unwrap_or(""),self.config.base_url,plan.endpoint));if let Some(body)=&plan.body{let mut body=String::from_utf8_lossy(body).into_owned();egui::ScrollArea::both().id_salt("hosting_payload").max_height(170.0).show(ui,|ui|{ui.add(egui::TextEdit::multiline(&mut body).font(egui::TextStyle::Monospace).interactive(false));});}ui.add_enabled_ui(!busy,|ui|{ui.checkbox(&mut self.confirmed,tr("I reviewed this exact remote operation and authorize sending it"));});if ui.add_enabled(!busy&&self.confirmed,egui::Button::new(tr("Send Reviewed Operation"))).clicked(){self.pending=None;self.confirmed=false;self.start(plan,trusted,true);}}
            if !self.output.is_empty(){egui::CollapsingHeader::new(tr("CLI response (first 64 KiB)")).default_open(true).show(ui,|ui|{ui.add(egui::TextEdit::multiline(&mut self.output).font(egui::TextStyle::Monospace).interactive(false).desired_rows(8));});}
        });(action,config_changed)
    }
}
impl Drop for Hosting{fn drop(&mut self){self.cancel();}}

