    #[test]
    fn typed_plans_use_json_stdin_and_bind_review_hash_account_host_and_visibility(){for provider in ["github","gitlab"]{let cfg=config(provider);let account=Some("tester".into());let exe=Path::new(if provider=="github"{"gh"}else{"glab"});let create=plan(&cfg,exe,Operation::Create{title:"Title $(touch NEVER)".into(),body:"@/etc/passwd is literal text".into(),base:"main".into(),head:"feature/quoted'branch".into(),draft:true},account.clone()).unwrap();assert!(create.write&&create.args.ends_with(&["--input".into(),"-".into()]));assert!(!create.args.iter().any(|arg|arg.contains("NEVER")));let data:Value=serde_json::from_slice(create.body.as_ref().unwrap()).unwrap();assert!(data.to_string().contains("@/etc/passwd"));let snippet=plan(&cfg,exe,Operation::Snippet{title:"Code".into(),name:"main.rs".into(),content:"fn main() {}".into(),public:false},account.clone()).unwrap();let data:Value=serde_json::from_slice(snippet.body.as_ref().unwrap()).unwrap();if provider=="github"{assert_eq!(data["public"],false);assert_eq!(data["files"]["main.rs"]["content"],"fn main() {}");}else{assert_eq!(data["visibility"],"private");assert_eq!(data["files"][0]["file_path"],"main.rs");}let review=plan(&cfg,exe,Operation::Review{number:7,sha:"a".repeat(40),event:"APPROVE".into(),body:String::new()},account.clone()).unwrap();assert!(String::from_utf8_lossy(review.body.as_ref().unwrap()).contains(&"a".repeat(40)));assert!(plan(&cfg,exe,Operation::Fork,None).is_err());assert!(plan(&cfg,exe,Operation::Snippet{title:"bad".into(),name:"../secret".into(),content:"body".into(),public:true},account).is_err());}}
    #[cfg(unix)]
    fn mock_cli(dir:&Path,provider:&str)->PathBuf{
        use std::os::unix::fs::PermissionsExt;
        let program=dir.join(if provider=="github"{"fake-gh"}else{"fake-glab"});let capture=serde_json::to_string(&dir.join("capture.jsonl").to_string_lossy()).unwrap();let root=serde_json::to_string(&dir.to_string_lossy()).unwrap();let script=format!(r#"#!/usr/bin/env python3
import sys,json,os,time,pathlib
root=pathlib.Path({root})
args=sys.argv[1:]
body=sys.stdin.read() if '--input' in args else ''
with open({capture},'a') as f:f.write(json.dumps({{'args':args,'body':body,'cwd':os.getcwd(),'project_env':os.environ.get('PROJECT_ONLY_SECRET')}})+'\n')
if args[:2]==['run','view']:
 print('cargo test passed');sys.exit()
if args==['--version']:
 print('glab version 1.36.0' if 'glab' in sys.argv[0] else 'gh version 2.45.0');sys.exit()
method=args[args.index('--method')+1]
endpoint=args[args.index('--method')+2]
if (root/'slow').exists():
 (root/'started').write_text('yes');time.sleep(3);(root/'late').write_text('bad')
if endpoint=='user':
 user=(root/'account').read_text() if (root/'account').exists() else 'tester'
 print(json.dumps({{'login':user,'username':user}}))
elif method=='POST':print('{{"ok":true}}')
elif '/pulls?' in endpoint:print('[{{"number":7,"title":"Review Rust","state":"open"}}]')
elif '/merge_requests?' in endpoint:print('[{{"iid":7,"title":"Review Rust","state":"opened"}}]')
elif '/trace' in endpoint:print('cargo test passed')
elif any('application/vnd.github.diff' in a for a in args) or endpoint.endswith('/raw_diffs'):print('diff --git a/src/lib.rs b/src/lib.rs\\n+pub fn reviewed(){{}}')
elif endpoint.endswith('/7'):print(json.dumps({{'number':7,'iid':7,'title':'Review Rust','head':{{'sha':'a'*40}},'sha':'a'*40}}))
elif '/actions/runs?' in endpoint:print('{{"workflow_runs":[{{"id":11,"name":"Rust CI","status":"completed"}}]}}')
elif '/pipelines?' in endpoint:print('[{{"id":11,"ref":"main","status":"success"}}]')
elif '/jobs?' in endpoint:print('{{"jobs":[{{"id":12,"name":"cargo test","status":"completed"}}]}}' if '/actions/' in endpoint else '[{{"id":12,"name":"cargo test","status":"success"}}]')
else:print('diff --git a/src/lib.rs b/src/lib.rs\n+pub fn reviewed(){{}}')
"#);std::fs::write(&program,script).unwrap();std::fs::set_permissions(&program,std::fs::Permissions::from_mode(0o700)).unwrap();program
    }
    #[cfg(unix)]
    #[tokio::test]
    async fn remote_writes_require_exact_confirmation_and_recheck_the_cli_account_without_running_project_code(){
        let dir=tempfile::tempdir().unwrap();let cfg=config("github");let exe=mock_cli(dir.path(),"github");let token=rc_dotnet::CancelToken::new();let pending=plan(&cfg,&exe,Operation::Fork,Some("tester".into())).unwrap();assert!(matches!(execute(&pending,false,true,&token).await,Err(Error::Trust)));assert!(matches!(execute(&pending,true,false,&token).await,Err(Error::Unconfirmed)));assert!(!dir.path().join("capture.jsonl").exists());
        std::fs::write(dir.path().join("account"),"changed").unwrap();assert!(matches!(execute(&pending,true,true,&token).await,Err(Error::Changed)));let captures=std::fs::read_to_string(dir.path().join("capture.jsonl")).unwrap();assert_eq!(captures.lines().count(),1);assert!(!captures.contains("POST"));
        std::fs::write(dir.path().join("account"),"tester").unwrap();execute(&pending,true,true,&token).await.unwrap();let captures=std::fs::read_to_string(dir.path().join("capture.jsonl")).unwrap();let last:Value=serde_json::from_str(captures.lines().last().unwrap()).unwrap();assert!(last["args"].as_array().unwrap().iter().any(|arg|arg=="POST"));assert_ne!(last["cwd"],dir.path().to_string_lossy().as_ref());assert!(last["project_env"].is_null());
    }
    #[cfg(unix)]
    #[tokio::test]
    async fn cancellation_kills_the_cli_and_prevents_a_delayed_write(){let dir=tempfile::tempdir().unwrap();let exe=mock_cli(dir.path(),"gitlab");std::fs::write(dir.path().join("slow"),"yes").unwrap();let pending=plan(&config("gitlab"),&exe,Operation::Requests,None).unwrap();let token=rc_dotnet::CancelToken::new();let child_token=token.clone();let task=tokio::spawn(async move{execute(&pending,true,false,&child_token).await});for _ in 0..100{if dir.path().join("started").exists(){break;}tokio::time::sleep(Duration::from_millis(10)).await;}assert!(dir.path().join("started").exists());token.cancel();assert!(matches!(task.await.unwrap(),Err(Error::Cancelled)));assert!(!dir.path().join("late").exists());}
    #[tokio::test]
    #[ignore="Read-only real installed gh/glab smoke test, using CLI credentials only for public GitHub GET"]
    async fn real_clis_accept_the_documented_commands_and_read_a_public_rust_pull_request(){let cancel=rc_dotnet::CancelToken::new();let cfg=Config{provider:"github".into(),base_url:"https://github.com".into(),project:"rust-lang/rust".into()};let version=plan(&cfg,Path::new("/usr/bin/gh"),Operation::Version,None).unwrap();assert!(String::from_utf8(execute(&version,true,false,&cancel).await.unwrap()).unwrap().starts_with("gh version"));let read=plan(&cfg,Path::new("/usr/bin/gh"),Operation::Requests,None).unwrap();let bytes=execute(&read,true,false,&cancel).await.unwrap();let value:Value=serde_json::from_slice(&bytes).unwrap();assert!(!items(Kind::Requests,true,&value).unwrap().is_empty());let cfg=config("gitlab");let version=plan(&cfg,Path::new("/tmp/crabcraft-glab/root/usr/bin/glab"),Operation::Version,None).unwrap();assert!(String::from_utf8(execute(&version,true,false,&cancel).await.unwrap()).unwrap().starts_with("glab version"));}
