            let writes=[Operation::Create{title:"Real Rust change".into(),body:"$(touch NEVER) is data".into(),base:"main".into(),head:"feature/rust".into(),draft:true},Operation::Review{number:7,sha:"a".repeat(40),event:"COMMENT".into(),body:"Reviewed Rust".into()},Operation::Review{number:7,sha:"a".repeat(40),event:"APPROVE".into(),body:String::new()},Operation::Fork,Operation::Snippet{title:"Rust sample".into(),name:"main.rs".into(),content:"fn main() {}".into(),public:false},Operation::Pipeline{number:11,retry:true},Operation::Pipeline{number:11,retry:false}];
